WITH r AS MATERIALIZED (SELECT id,locale,seed_media_id,expected_item_count,served_item_payload FROM recommendation_request WHERE surface_version='watch-below-player-v1' AND created_at>='2026-09-29T18:42:00Z' AND created_at<'2026-09-30T18:42:00Z' AND expected_item_count BETWEEN 1 AND 5), contexts AS (
SELECT r.*,coalesce(r.served_item_payload->'items'->i.id->'presentation',i.presentation)->>'audioLanguageSlug' audio_language_slug FROM r CROSS JOIN LATERAL (SELECT id,presentation FROM recommendation_served_item WHERE request_id=r.id ORDER BY position LIMIT 1) i)
SELECT r.locale,r.audio_language_slug,r.seed_media_id,v.slug,count(*) requests,min(expected_item_count) min_cards,max(expected_item_count) max_cards FROM contexts r JOIN video v ON v.id=r.seed_media_id GROUP BY 1,2,3,4 ORDER BY requests DESC LIMIT 20;
SELECT t.language,count(DISTINCT t.video_id) videos_with_compatible_embeddings,count(DISTINCT t.video_id) FILTER(WHERE v.deleted_at IS NULL AND NOT ('watch'=ANY(v.restrict_view_platforms))) watch_eligible,count(DISTINCT t.video_id) FILTER(WHERE EXISTS(SELECT 1 FROM video_locale l WHERE l.video_id=t.video_id AND l.locale=t.language AND l.status='published' AND l.deleted_at IS NULL)) published_same_locale FROM video_transcript t JOIN video v ON v.id=t.video_id CROSS JOIN content_embedding_contract_pointer p JOIN content_embedding_contract c ON c.id=p.active_contract_id WHERE t.language IN ('en','te','zh','ckb','fr') AND t.embedding_provider=c.storage_provider AND t.model=c.storage_model AND t.dimensions=c.storage_dimensions AND t.embedding_native_dimensions=c.storage_native_dimensions AND t.embedding_transform_version IS NOT DISTINCT FROM c.storage_transform_version AND EXISTS(SELECT 1 FROM video_transcript_chunk ch WHERE ch.transcript_id=t.id AND ch.language=t.language AND ch.embedding IS NOT NULL AND ch.model=c.storage_model AND ch.dimensions=c.storage_dimensions) GROUP BY 1 ORDER BY 1;
